```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    // Definir la palabra a buscar
    std::string search_word = "ejemplo";

    // Abrir el archivo de texto
    std::ifstream file("archivo.txt");

    if (!file.is_open()) {
        std::cerr << "Error al abrir el archivo de texto." << std::endl;
        return 1;
    }

    // Variable para contar las apariciones
    int count = 0;

    // Leer línea por línea del archivo
    std::string line;
    while (getline(file, line)) {
        // Reemplazar los espacios en blanco por límites de palabras
        std::replace(line.begin(), line.end(), ' ', '\n');

        // Separar la línea en palabras
        std::istringstream iss(line);
        std::string word;
        while (iss >> word) {
            // Si encontramos la palabra a buscar, aumentamos el conteo
            if (word == search_word) {
                count++;
            }
        }
    }

    // Cerrar el archivo de texto
    file.close();

    // Mostrar el conteo de apariciones
    std::cout << "La palabra '" << search_word << "' aparece " << count << " veces en el archivo." << std::endl;

    return 0;
}
```

En este ejemplo, se asume que el archivo de texto se llama "archivo.txt" y se encuentra en el mismo directorio que el ejecutable.

